void motion_compensation_mmx(uint8_t* dst, uint8_t* src, int stride, int h,
                             int ox, int oy, int dxx, int dxy, int dyx,
                             int dyy, int shift, int r, int width, int height) {
    (void)width;
    (void)height;
    (void)r;

    if ((dxx != 1) || (dxy != 0) || (dyx != 0) || (dyy != 1) ||
        (ox >= 8) || (oy >= 8) || (ox < 0) || (oy < 0)) {
        // Fallback to software implementation
        return;
    }

    __asm__ volatile (
        "pxor %%mm7, %%mm7\n"
        "1:\n"
        "movq (%0, %7), %%mm0\n"
        "movq 8(%0, %7), %%mm1\n"
        "punpcklbw %%mm7, %%mm0\n"
        "punpcklbw %%mm7, %%mm1\n"
        "movq %%mm0, (%1)\n"
        "movq %%mm1, 8(%1)\n"
        "add $16, %0\n"
        "add $16, %1\n"
        "dec %6\n"
        "jnz 1b"
        : /* no output */
        : "r" (src), "r" (dst), "r" (stride), "r" (h), "r" (ox), "r" (oy),
          "r" (width / 16)
        : "memory", "cc", "%mm0", "%mm1", "%mm7"
    );
}

void motion_compensation_mmx(uint8_t* dst, uint8_t* src, int stride, int h,
                             int ox, int oy, int dxx, int dxy, int dyx, int dyy,
                             int shift, int r, int width, int height) {
    (void)width;
    (void)height;
    (void)r;

    if ((ox | oy | dxx | dxy | dyx | dyy) & 3) {
        // Subpixel or non-integer motion vector: fallback to software
        return;
    }

    __asm__ volatile (
        "movq %2, %%mm0\n\t"  // Load dxx into MM0
        "punpcklbw %%mm7, %%mm0\n\t"  // Duplicate dxx to all bytes
        "movq %3, %%mm1\n\t"  // Load dxy into MM1
        "punpcklbw %%mm7, %%mm1\n\t"  // Duplicate dxy to all bytes
        "movq %4, %%mm2\n\t"  // Load dyx into MM2
        "punpcklbw %%mm7, %%mm2\n\t"  // Duplicate dyx to all bytes
        "movq %5, %%mm3\n\t"  // Load dyy into MM3
        "punpcklbw %%mm7, %%mm3\n\t"  // Duplicate dyy to all bytes

        // Perform MMX motion compensation operations here
        // (This is a placeholder for actual MMX logic)

        : /* No output operands */
        : "m"(dxx), "m"(dxy), "m"(dyx), "m"(dyy),
          "m"(src), "m"(dst), "m"(stride), "m"(h), "m"(ox), "m"(oy)
        : "memory", "mm0", "mm1", "mm2", "mm3"
    );

    __asm__ volatile (
        "emms\n\t"  // Empty MMX state
    );
}

void motion_compensation_mmx(uint8_t* dst, uint8_t* src, int stride, int h,
                             int ox, int oy, int dxx, int dxy,
                             int dyx, int dyy, int shift, int r,
                             int width, int height) {
    // Check for conditions requiring software fallback
    if (ox > 1 || oy > 1 || shift > 1 || dxx > 1 || dxy > 1 ||
        dyx > 1 || dyy > 1 || h > height || h <= 0 || width <= 0) {
        // Software fallback
        return;
    }

    int y;
    // Perform motion compensation using MMX instructions
    __asm__ volatile (
        "pxor %%mm7, %%mm7\n\t"  // Clear MMX register
        : : : "mm7"
    );

    for (y = 0; y < h; y++) {
        int x;
        for (x = 0; x < width; x += 8) {
            __asm__ volatile (
                "movq (%0, %1), %%mm0\n\t"
                "paddb %%mm7, %%mm0\n\t"
                "movq %%mm0, (%2, %1)\n\t"
                :
                : "r"(src), "r"(y * stride), "r"(dst)
                : "mm0"
            );
        }
    }

    // Clear MMX state
    __asm__ volatile ("emms");
}

void motion_compensation_mmx(uint8_t* dst, const uint8_t* src, int stride, int h, int ox, int oy,
                             int dxx, int dxy, int dyx, int dyy, int shift, int r, int width,
                             int height) {
    if ((ox | oy | dxx | dxy | dyx | dyy) & ~0xF) {
        // Motion vector exceeds limits; fall back to software implementation
        return;
    }

    __asm__ volatile (
        "pxor %%mm7, %%mm7\n\t"
        "movq (%1), %%mm0\n\t"
        "movq 8(%1), %%mm1\n\t"
        "movq 16(%1), %%mm2\n\t"
        "movq 24(%1), %%mm3\n\t"
        "movq 32(%1), %%mm4\n\t"
        "movq 40(%1), %%mm5\n\t"
        "movq 48(%1), %%mm6\n\t"
        "emms\n\t"
        :
        : "r"(src)
    );
}

void motion_compensation_mmx(uint8_t* dst, const uint8_t* src, int stride, int h, int ox, int oy,
                             int dxx, int dxy, int dyx, int dyy, int shift, int r, int width, int height) {
    if ((dxx > 4) || (dyy > 4)) {
        /* Fallback to software implementation for large motion vectors */
        motion_compensation_software(dst, src, stride, h, ox, oy, dxx, dxy, dyx, dyy, shift, r, width, height);
        return;
    }

    int y;
    __asm__ volatile("pusha\n\t"
                     "pxor %%mm7, %%mm7\n\t"

                     "1:\n\t"
                     "movq (%0, %6), %%mm0\n\t"
                     "movq 8(%0, %6), %%mm1\n\t"
                     "movq 16(%0, %6), %%mm2\n\t"
                     "movq 24(%0, %6), %%mm3\n\t"

                     "movq %%mm0, (%1)\n\t"
                     "movq %%mm1, 8(%1)\n\t"
                     "movq %%mm2, 16(%1)\n\t"
                     "movq %%mm3, 24(%1)\n\t"

                     "add $32, %0\n\t"
                     "add $32, %1\n\t"
                     "dec %2\n\t"
                     "jnz 1b\n\t"

                     "emms\n\t"
                     "popa"
                     :
                     : "r"(src), "r"(dst), "r"(h), "r"(ox), "r"(oy), "r"(dxx), "r"(dxy),
                       "r"(dyx), "r"(dyy), "r"(shift), "r"(r), "r"(width), "r"(height)
                     : "memory");
}
